import {renderWelcome,renderOperations} from './presentation.js';
import {summary,scope,filteredWorkCases,uniquePeople,openRequirements,nextAction,journeySteps,recommendations,CHAT_SUGGESTIONS,ACCEPTED,REGISTERED} from './workflow.js';

export function renderLanding(k){return renderWelcome(k);}

const base=f=>({year:f.year,route:f.route,prodi:f.prodi,region:f.region});
export function renderDashboard(k){return renderOperations(k);}

export function renderJourney(k,c){const {state,intro,demo,btn,esc,pill,fmt,icon,journeyMarkup}=k;
  const action=nextAction(state,c.id);
  return intro('LANGKAH SAYA','Sekarang, apa langkahku?','Periksa setiap persyaratan, catatan pemeriksaan, dan riwayat pengajuan.',btn('Panduan cetak','print-guide','secondary','download')+btn('Kalender tenggat','download-calendar','secondary','calendar'))+demo()+`<div class="candidate-identity"><strong>${esc(c.name)}</strong><span>${esc(c.prodi)} · Jalur ${esc(c.route||'belum tersedia')} · ${esc(c.id)}</span>${pill(c.source)}</div><div class="workflow-next"><span class="eyebrow">TINDAKAN YANG SESUAI STATUSMU</span><h2>${esc(action.title)}</h2><p>${esc(action.text)}</p><small>Data diperbarui ${fmt(state.updatedAt)} · jadwal simulasi</small></div><div class="two-col"><section class="panel requirements-panel"><div class="panel-head"><div><h2>Daftar persyaratan</h2><p>Status setiap dokumen mengikuti pengiriman dan pemeriksaan.</p></div>${pill(c.status)}</div>${c.requirements.map(r=>`<article class="requirement" id="req-${r.id}"><div class="requirement-heading"><h3>${esc(r.name)}</h3>${pill(r.applicable?r.status:'Tidak berlaku')}</div><p class="requirement-deadline">${icon('calendar')} ${fmt(r.deadline)} · simulasi</p>${r.reason?`<div class="inline-alert"><strong>Catatan petugas</strong><br>${esc(r.reason)}</div>`:''}${r.file?`<div class="file-row">${esc(r.file.name)} · ${Math.ceil(r.file.size/1024)} KB<br><small>Metadata demo; isi berkas tidak diunggah ke server.</small></div>`:''}${r.applicable&&c.source==='Diterima'&&['Perlu tindakan','Perlu perbaikan'].includes(r.status)?`<form class="requirement-upload" data-requirement="${r.id}"><label class="field">${r.status==='Perlu perbaikan'?'Pilih dokumen perbaikan':'Pilih berkas'}<input name="document" type="file" accept=".pdf,.jpg,.jpeg,.png" required><small>PDF, JPG, atau PNG · maksimum 5 MB · gunakan berkas contoh.</small></label><p class="error" role="alert"></p><button type="submit" class="btn">${r.status==='Perlu perbaikan'?'Kirim perbaikan':'Kirim untuk diperiksa'} ${icon('arrow')}</button></form>`:`<p class="requirement-note">${r.status==='Menunggu verifikasi'?'Dokumen sudah diterima. Tidak perlu dikirim ulang selama diperiksa.':r.status==='Selesai'?'Persyaratan sudah diverifikasi petugas.':'Kewajiban ini belum berlaku pada status pendaftaranmu.'}</p>`}</article>`).join('')}</section><aside class="stack"><section class="panel"><h2>Perjalanan pendaftaran</h2>${journeyMarkup(c)}<p class="login-note">Tidak ada persentase progres buatan. Setiap tahap mengikuti status sumber.</p></section><section class="panel"><h2>Ada yang menghambat?</h2><p>Jelaskan kendalamu kepada petugas atau tanyakan status melalui FAQ terstruktur.</p>${btn('Minta bantuan','new-ticket','secondary','help')}<button class="text-btn section-gap" data-action="faq-open">Tanya status demo ${icon('arrow')}</button></section></aside></div><section class="panel section-gap"><h2>Riwayat pengiriman & pemeriksaan</h2>${c.history.length?`<ol class="document-history">${c.history.map(h=>`<li><strong>${esc(h.requirement)} · ${esc(h.status)}</strong><small>${esc(h.actor)} · ${fmt(h.time)}</small>${h.file?`<p>${esc(h.file.name)}</p>`:''}${h.reason?`<p>${esc(h.reason)}</p>`:''}</li>`).join('')}</ol>`:`<p>Belum ada pengiriman baru pada simulasi ini. Status awal berasal dari data latihan.</p>`}</section>`;
}
export function renderJourneySteps(c,icon,esc){return `<ol class="journey">${journeySteps(c).map((step,i)=>`<li><span class="step-number ${step.status==='Selesai'?'done':step.status==='Perlu tindakan'||step.status==='Perlu perbaikan'||step.status==='Sedang diproses'?'current':''}">${step.status==='Selesai'?icon('check'):i+1}</span><div><h3>${esc(step.name)}</h3><p>${esc(step.status)}</p></div></li>`).join('')}</ol>`;}

export function renderCaseTable(k,rows,limit=Infinity){const {state,esc,pill,icon,fmt}=k;if(!rows.length)return `<div class="empty"><h3>Tidak ada calon mahasiswa pada cakupan ini.</h3><p>Ubah filter atau pilih kategori lain. Tidak ada data tambahan yang dibuat.</p></div>`;
  return `<div class="table-wrap"><table class="responsive-table work-table"><thead><tr><th>CALON MAHASISWA / APLIKASI</th><th>PRODI / JALUR</th><th>TAHAP & KEWAJIBAN</th><th>TENGGAT</th><th>KENDALA DILAPORKAN</th><th>PETUGAS</th><th>TINDAK LANJUT TERAKHIR</th><th>TINDAKAN</th></tr></thead><tbody>${rows.slice(0,limit).map(c=>{const tickets=state.tickets.filter(t=>t.caseId===c.id&&t.status!=='Selesai');const reqs=openRequirements(c);const waiting=c.requirements.filter(r=>r.applicable&&r.status==='Menunggu verifikasi');return `<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${c.personId?'ID orang tersedia':'ID orang belum tersedia'}<br>Status sumber: ${esc(c.source)}</small></td><td data-label="Prodi / jalur">${esc(c.prodi)}<small>${esc(c.route||'Belum tersedia')}</small></td><td data-label="Tahap & kewajiban">${esc(c.stage===3?'Aktivasi mahasiswa':c.stage===2?'Daftar ulang':'Seleksi / pengumuman')}<small>${reqs.length?reqs.map(r=>esc(r.name)).join(', '):waiting.length?'Dokumen menunggu pemeriksaan':esc(c.status)}</small>${pill(c.status)}</td><td data-label="Tenggat">${fmt(c.deadline,false)}${c.deadline&&new Date(c.deadline)<new Date(state.now)&&reqs.length?'<small>Terlewati · perlu ditinjau</small>':''}</td><td data-label="Kendala">${tickets.length?tickets.map(t=>esc(t.category)+' · '+esc(t.id)).join('<br>'):'Belum ada kendala dilaporkan'}</td><td data-label="Petugas">${esc(c.owner)}</td><td data-label="Tindak lanjut terakhir">${c.lastFollowup?fmt(c.lastFollowup,false):'Belum ada tindak lanjut'}</td><td><button class="table-link" data-case="${esc(c.id)}" aria-label="Buka kasus ${esc(c.name)}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;
}
export function renderFollowup(k){const {state,filters,intro,demo,filterbar,esc,icon,pill,fmt}=k,rows=filteredWorkCases(state,filters);const names={total:'Pendaftar unik',accepted:'Dinyatakan diterima',registered:'Daftar ulang selesai',active:'Mahasiswa aktif',open:'Kewajiban terbuka',tickets:'Tiket belum selesai',review:'Menunggu pemeriksaan',overdue:'Tenggat terlewati'};
  const raw=summary(state,base(filters)),ids=new Set(rows.map(c=>c.id));const tickets=raw.tickets.filter(t=>ids.has(t.caseId));
  return intro('TINDAK LANJUT','Siapa yang perlu dibantu?','Telusuri angka ke calon mahasiswa, kewajiban, tenggat, dan penanggung jawabnya.')+demo()+filterbar(true)+`<div class="tabs">${[['','Semua aplikasi'],['open','Kewajiban terbuka'],['review','Menunggu pemeriksaan'],['tickets','Tiket terbuka'],['overdue','Tenggat terlewati']].map(([id,label])=>`<button class="tab ${filters.metric===id?'active':''}" data-metric="${id}">${label}</button>`).join('')}</div>${filters.metric?`<div class="metric-context"><strong>${esc(names[filters.metric]||'Cakupan terpilih')}</strong><span>${uniquePeople(rows)??'Belum dapat dihitung'} orang unik · ${rows.length} aplikasi${filters.metric==='tickets'?' · '+tickets.length+' tiket terbuka':''}</span><button class="text-btn" data-metric="">Hapus kategori ${icon('close')}</button></div>`:''}${filters.metric==='tickets'?`<section class="panel section-gap"><h2>Tiket pembentuk angka</h2>${tickets.length?tickets.map(t=>`<div class="list-row"><div class="grow"><h3>${esc(t.id)} · ${esc(state.cases.find(c=>c.id===t.caseId)?.name)}</h3><p>${esc(t.text)}</p><small>${esc(t.owner)} · ${fmt(t.created,false)}</small></div><div>${pill(t.status)}<br><button class="text-btn" data-ticket="${t.id}">Buka tiket ${icon('arrow')}</button></div></div>`).join(''):'<p>Tidak ada tiket terbuka pada cakupan ini.</p>'}</section>`:''}<section class="panel queue-panel section-gap"><div class="panel-head"><div><h2>Daftar calon mahasiswa & aplikasi</h2><p>${rows.length} aplikasi sesuai filter. Satu orang dapat memiliki lebih dari satu aplikasi.</p></div></div>${renderCaseTable(k,rows.sort((a,b)=>new Date(a.deadline||'2099-01-01')-new Date(b.deadline||'2099-01-01')))}</section><p class="count-definition">Prioritas dapat ditinjau dari tenggat, dokumen menunggu petugas, dan tiket yang belum ditangani. Melewati tenggat tidak membatalkan penerimaan otomatis.</p>`;
}

export function requirementReview(k,c){const {esc,pill,fmt}=k;
  return `<section class="case-requirements"><h3>Persyaratan & bukti pengajuan</h3><p class="login-note">Pemeriksaan ini adalah simulasi metadata. Isi berkas tidak tersimpan di server.</p>${c.requirements.filter(r=>r.applicable).map(r=>`<article class="requirement"><div class="requirement-heading"><h3>${esc(r.name)}</h3>${pill(r.status)}</div>${r.file?`<p class="file-row">${esc(r.file.name)} · ${Math.ceil(r.file.size/1024)} KB</p>`:'<p>Belum ada berkas diajukan.</p>'}${r.reason?`<p class="error">${esc(r.reason)}</p>`:''}${r.status==='Menunggu verifikasi'?`<form class="document-review" data-case-id="${c.id}" data-requirement="${r.id}"><label class="field">Hasil pemeriksaan<select name="decision" aria-label="Hasil pemeriksaan"><option value="Selesai">Dokumen sesuai</option><option value="Perlu perbaikan">Perlu perbaikan</option></select></label><label class="field">Kategori alasan<select name="reasonCode" aria-label="Kategori alasan"><option value="other">Lainnya / tidak berlaku</option><option value="unreadable">Dokumen tidak terbaca</option><option value="incomplete">Informasi dokumen belum lengkap</option></select></label><label class="field">Catatan petugas<textarea name="reason" maxlength="1000" placeholder="Wajib diisi bila perlu perbaikan"></textarea></label><p class="error" role="alert"></p><button class="btn" type="submit">Simpan hasil pemeriksaan</button></form>`:''}<small>${r.history.length?'Pembaruan '+fmt(r.history[0].time,false):'Status awal data latihan'}</small></article>`).join('')}</section>`;
}

export function renderChat(k,role){const {state,esc,btn,fmt}=k,key=role==='public'?'public':role;const messages=state.chats[key]||[];
  return `<div class="chat-disclosure"><strong>Demo FAQ terstruktur</strong><p>Jawaban dari panduan latihan dan status demo milikmu. Belum memakai AI atau akun nyata.</p></div><div class="chat-messages" aria-label="Percakapan Tanya ADMIRA">${messages.length?messages.map(m=>`<article class="chat-message ${m.actor==='user'?'from-user':'from-assistant'}"><strong>${m.actor==='user'?'Kamu':'Tanya ADMIRA'}</strong><p>${esc(m.text)}</p>${m.actor==='assistant'?`<small>${m.kind==='personal'?'Informasi pribadi demo':m.kind==='unavailable'?'Informasi belum dapat dipastikan':'Informasi umum'}<br>Sumber: ${esc(m.source)}<br>Diperbarui ${fmt(m.updatedAt)}</small><div class="chat-response-actions">${(m.actions||[]).map(a=>btn(esc(a.label),a.action,'secondary')).join('')}</div>`:''}</article>`).join(''):'<p>Pilih pertanyaan atau tulis pertanyaan tentang pendaftaran.</p>'}</div><div class="chat-suggestions">${CHAT_SUGGESTIONS.map((q,i)=>`<button data-chat-question="${i}">${esc(q)}</button>`).join('')}</div><form id="chat-form"><label class="field">Pertanyaanmu<input name="question" required maxlength="500" autocomplete="off" placeholder="Contoh: apa langkah saya berikutnya?"></label><div class="actions"><button class="btn" type="submit">Tanyakan</button>${role==='student'?btn('Teruskan ke petugas','chat-handoff','secondary'):''}</div></form>`;
}

export function renderEvaluation(k){const {state,filters,intro,demo,filterbar,esc,fmt,pill,icon,evalTab}=k;
  const recs=recommendations(state,base(filters));const plans=state.actionPlans.filter(p=>Object.entries(base(filters)).every(([key,value])=>!value||p.scope[key]===value));
  const planRows=plans.length?plans.map(p=>`<article class="plan-row"><div><span class="eyebrow">${esc(p.scope.year||'Semua periode')} · ${esc(p.owner)}</span><h3>${esc(p.title)}</h3><p>${esc(p.proposal)}</p><small>Evaluasi ${esc(p.reviewDate)} · ${esc(p.indicator)}</small>${p.result?`<p class="plan-result">Hasil: ${esc(p.result)}</p>`:''}</div><div>${pill(p.status)}<button class="text-btn" data-plan="${p.id}">Buka rencana ${icon('arrow')}</button></div></article>`).join(''):'<div class="empty"><h3>Belum ada rencana pada cakupan ini.</h3><p>Tinjau rekomendasi lalu simpan usulan menjadi rencana tindakan.</p></div>';
  const findings=`<div class="recommendations">${recs.map((r,i)=>{const plan=plans.find(p=>p.recommendationId===r.id&&p.status!=='Ditutup');return `<article class="panel recommendation" data-plan-state="${esc(plan?.status||'Perlu ditinjau')}"><div class="recommendation-top"><span class="section-number">0${i+1}</span>${pill(plan?.status||'Perlu ditinjau')}</div><h2>${esc(r.title)}</h2><div class="recommendation-layout"><section class="recommendation-evidence"><span class="eyebrow">02 / BUKTI DATA · ${esc(r.period)}</span><p>${esc(r.evidence)}</p><small>Sumber: ${esc(r.source)}<br>Diperbarui ${fmt(r.updatedAt)}<br>Periode: ${esc(r.period)}</small></section><div><section class="recommendation-step"><span class="eyebrow">01 / TEMUAN</span><p>${esc(r.finding)}</p><small>Kelompok / proses: ${esc(r.target)}</small></section><section class="recommendation-step"><span class="eyebrow">03 / USULAN TINDAKAN</span><p>${esc(r.proposal)}</p><button class="btn secondary" data-recommendation="${r.id}">Jadikan rencana tindakan ${icon('arrow')}</button></section><section class="recommendation-step"><span class="eyebrow">04 / EVALUASI</span><p>${esc(r.indicator)}</p><small>Pelaksana & waktu evaluasi: ${plan?esc(plan.owner)+' · '+esc(plan.reviewDate):'Belum ditetapkan. Tentukan saat menyusun rencana tindakan.'}</small></section></div></div><div class="recommendation-limit">${icon('info')}${esc(r.limit)}</div></article>`;}).join('')}</div>`;
  return intro('EVALUASI DAN REKOMENDASI','Dari temuan, menuju perbaikan.','Tinjau bukti, simpan usulan tindakan, dan catat hasilnya. Keputusan tetap memerlukan peninjauan manusia.')+demo()+filterbar()+`<div class="tabs"><button class="tab ${evalTab==='findings'?'active':''}" data-eval-tab="findings">Temuan & usulan</button><button class="tab ${evalTab==='plans'?'active':''}" data-eval-tab="plans">Rencana tindakan (${plans.length})</button></div>${evalTab==='plans'?`<section class="panel"><div class="panel-head"><div><h2>Register tindakan yang dapat ditelusuri</h2><p>Dasar rekomendasi disimpan sebagai snapshot saat rencana dibuat.</p></div></div>${planRows}</section>`:findings}`;
}
